---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class HomeInfo : IDataInfo
local HomeInfo = class("HomeInfo", IDataInfo)

function HomeInfo:onCreate()
    ---key, defValue, toSelf, toOther, saveDB
    self:initKey(Define.HomeInfoKey.MasterId, 0, true, false, false)
    self:initKey(Define.HomeInfoKey.OriginPos, VectorUtil.newVector3(1, 3, 1), true, false, false)
    self:initKey(Define.HomeInfoKey.Visitors, {}, false, false, false)
    self:initKey(Define.HomeInfoKey.SetBanFishingRod, false, true, false, true)
    self:initKey(Define.HomeInfoKey.SetBanGun, false, true, false, true)
    self:initKey(Define.HomeInfoKey.SetBanFlying, false, true, false, true)
    self:initKey(Define.HomeInfoKey.SetBanHideAndSeek, true, true, false, true)
    self:initKey(Define.HomeInfoKey.NightEffect, true, true, false, true)
    self:initKey(Define.HomeInfoKey.BanFishingRod, false, true, false, false)
    self:initKey(Define.HomeInfoKey.BanGun, false, true, false, false)
    self:initKey(Define.HomeInfoKey.BanFlying, false, true, false, false)
    self:initKey(Define.HomeInfoKey.BanHideAndSeek, true, true, false, false)
    self:initKey(Define.HomeInfoKey.Loading, false, true, false, false)
    self:initKey(Define.HomeInfoKey.BanLightBlock, false, true, true, true)
    self:initKey(Define.HomeInfoKey.BanPreciousBlock, false, true, true, true)
    self:initKey(Define.HomeInfoKey.BanDangerBlock, false, true, true, true)
    self:initKey(Define.HomeInfoKey.EditHome, true, true, true, true)
end

---@param player SBasePlayer | CBasePlayer
function HomeInfo:initPlayer(player)
    if isClient then
        return
    end
    self:addKeyObserver(Define.HomeInfoKey.BanHideAndSeek, function(_, _, ban)
        if ban and player.hide_and_seek:inHideAndSeek() then
            player.hide_and_seek:setValue(Define.HideAndSeekInfoKey.HideAndSeekId, 0)
        end
    end)
    self:addKeyObserver(Define.HomeInfoKey.SetBanHideAndSeek, function(_, _, ban)
        self:setValue(Define.HomeInfoKey.BanHideAndSeek, ban)
    end)
end

---@param home HomeInfo
function HomeInfo:setMaster(masterId, home)
    self:setValue(Define.HomeInfoKey.MasterId, masterId)
    if home then
        self:setValue(Define.HomeInfoKey.BanFishingRod, home:getValue(Define.HomeInfoKey.SetBanFishingRod))
        self:setValue(Define.HomeInfoKey.BanGun, home:getValue(Define.HomeInfoKey.SetBanGun))
        self:setValue(Define.HomeInfoKey.BanFlying, home:getValue(Define.HomeInfoKey.SetBanFlying))
        self:setValue(Define.HomeInfoKey.BanHideAndSeek, home:getValue(Define.HomeInfoKey.SetBanHideAndSeek))
    else
        self:reset()
    end
end

function HomeInfo:reset()
    self:setValue(Define.HomeInfoKey.BanFishingRod, false)
    self:setValue(Define.HomeInfoKey.BanGun, false)
    self:setValue(Define.HomeInfoKey.BanFlying, false)
    self:setValue(Define.HomeInfoKey.BanHideAndSeek, true)
end

function HomeInfo:inHomeArea(worldPos)
    local savePos = self:toSavePos(worldPos)
    local maxSize = Define.MaxHomeSize
    if savePos.x < 0 or savePos.y < 0 or savePos.z < 0
            or savePos.x >= maxSize or savePos.y >= maxSize or savePos.z >= maxSize then
        return false
    end
    return true
end

function HomeInfo:inHomeAreaXZ(worldPos)
    local savePos = self:toSavePos(worldPos)
    local maxSize = Define.MaxHomeSize
    if savePos.x < 0 or savePos.z < 0 or savePos.x >= maxSize or savePos.z >= maxSize then
        return false
    end
    return true
end

function HomeInfo:toWorldPos(savePos)
    return VectorUtil.add3(savePos, self:getValue(Define.HomeInfoKey.OriginPos))
end

function HomeInfo:toSavePos(worldPos)
    return VectorUtil.sub3(worldPos, self:getValue(Define.HomeInfoKey.OriginPos))
end

return HomeInfo